  (9, 'Gavilan College', '41394', 38948144064, '{"blocks":[{"courses":[{"alternatives":[],"catalog_addition":false,"code":"ACCT 20","units":4,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"ACCT 21","units":4,"units_max":null},{"alternatives":[],"catalog_addition":true,"code":"ECON 1","units":3,"units_max":null},{"alternatives":[],"catalog_addition":true,"code":"ECON 2","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"BUS 80","units":3,"units_max":null}],"minimum":null,"name":"Requirements","option_group":null,"rule":"all","stated":{"max":17,"min":17}},{"courses":[{"alternatives":[],"catalog_addition":false,"code":"MATH 6","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"MATH 7","units":3,"units_max":null}],"minimum":1,"name":"Choose One Course:","option_group":null,"rule":"choose_courses","stated":{"max":3,"min":3}},{"courses":[{"alternatives":[{"catalog_addition":false,"code":"ECON 11","units":4}],"catalog_addition":false,"code":"BUS 11","units":4,"units_max":null},{"alternatives":[],"catalog_addition":true,"code":"STAT C1000","units":4,"units_max":null}],"minimum":1,"name":"Choose One Course:","option_group":null,"rule":"choose_courses","stated":{"max":4,"min":3}},{"courses":[{"alternatives":[],"catalog_addition":false,"code":"BUS 1","units":3,"units_max":null},{"alternatives":[{"catalog_addition":false,"code":"BOT 100","units":3}],"catalog_addition":false,"code":"BUS 100","units":3,"units_max":null}],"minimum":1,"name":"Choose One Course:","option_group":null,"rule":"choose_courses","stated":{"max":3,"min":3}}],"program":{"careers":[],"degree_elective_units":{"max":null,"min":null},"degree_total":{"max":61,"min":60},"electives_fill_degree":false,"ge_pattern":"Cal-GETC","ge_units":{"max":34,"min":34},"measure":"units","open_elective_units":null,"outcomes":["Apply communication principles and appropriate information technology to the production of emails, letters, memos, resumes, reports, and various other documents.","Describe existing and emerging information technologies that assist in effective business decision-making or facilitate communication.","Discuss the causes of macroeconomic (business cycle) fluctuations, and the effects these fluctuations have on business owners.","Apply cost-benefit analysis to resource allocation choices made in a business setting.","Explain accounting terminology, concepts, principles, and frameworks.","Perform accounting-related calculations, and demonstrate the ability to use accounting methods and procedures, to solve accounting and business related questions and problems.","Apply legal analysis in planning and decision making to avoid legal conflicts in business decisions.","Develop and exhibit high standards of professional practice, demonstrating awareness of ethical and social responsibilities in today’s multi-cultural, team-oriented, rapidly-changing environment."],"section_heading":"Business Administration 2.0 - A.S.-T Degree","total_units":{"max":27,"min":26}}}'::jsonb, '{"arithmetic":"unequal","coverage":true,"invented":true,"listed":13,"placed":10}'::jsonb, '{"arithmetic":"unequal","confidence":{"catalog_year":100,"course_list_match":77,"ge_pattern":100,"source":100,"unit_arithmetic":40},"coverage":true,"gaps":["noted_figures_differ"],"invented":true,"listed":13,"placed":10}'::jsonb)),
c as (select count(*) filter (where r.checked is true) as n,
             coalesce(json_agg(v.i order by v.i) filter (where r.checked is true), '[]'::json) as keys
        from v join public.program_requirement_records r
          on r.college = v.college and r.control_number = v.control_number),
f as (select count(*) as n, coalesce(json_agg(v.i order by v.i), '[]'::json) as keys
        from v join public.program_requirement_records r
          on r.college = v.college and r.control_number = v.control_number
        join lateral (select pv.verdict, pv.requirements_fp from public.program_record_verdicts pv
                       where pv.college = v.college and pv.control_number = v.control_number
                       order by pv.id desc limit 1) lv on true
       where lv.verdict = 'confirm' and lv.requirements_fp = public.program_record_fp(r.record)),
e(expect) as (values (9)),
u as (
update public.program_requirement_records r
   set checks = v.after_checks
  from v
 where r.college = v.college and r.control_number = v.control_number
   and r.extracted_run = v.extracted_run and r.checks = v.before_checks and r.record = v.before_record
   and r.checked is not true
returning v.i),
s as (select count(*) as n, coalesce(json_agg(i order by i), '[]'::json) as keys from u)
select case when f.n > 0
            then ('s739m piles confirm guard: ' || f.n || ' rows hold a matching confirm verdict ' || f.keys::text)::int::text::json
            when s.n = e.expect - c.n
            then json_build_object('returned', s.n, 'keys', s.keys, 'skipped_checked', c.keys)
            else ('s739m piles guard: the UPDATE matched ' || s.n || ' rows, the plan names ' || (e.expect - c.n))::int::text::json end as returned
  from s, c, e, f;
